<template><div v-loading="loading"><el-button link @click="router.push('/basic/suppliers/factories')">← {{t('suppliers.backFactories')}}</el-button><div v-if="factory" class="hero"><div><small>{{factory.code}}</small><h2>{{displayName}}</h2><p>{{supplierName||factory.supplierName}} · {{factory.city||'—'}}</p></div><el-button v-if="auth.can('masterdata:factory:write')" @click="editOpen=true">{{t('suppliers.editProfile')}}</el-button></div><el-card v-if="factory" shadow="never"><el-tabs v-model="tab" @tab-change="loadTab"><el-tab-pane :label="t('suppliers.profile')" name="profile"><el-descriptions :column="2" border><el-descriptions-item :label="t('suppliers.belongsSupplier')">{{supplierName||factory.supplierId}}</el-descriptions-item><el-descriptions-item :label="t('common.status')">{{statusLabel(factory.status)}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.factoryName')">{{factory.nameZh||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.factoryNameEn')">{{factory.nameEn||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.country')">{{factory.countryCode?countryName(factory.countryCode,locale):'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.timezone')">{{factory.timezone||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.factoryAddress')" :span="2">{{[factory.stateProvince,factory.city,factory.district,factory.address].filter(Boolean).join(' ')||'—'}}</el-descriptions-item><el-descriptions-item :label="t('suppliers.remark')" :span="2">{{factory.remark||'—'}}</el-descriptions-item></el-descriptions></el-tab-pane>
<el-tab-pane :label="t('suppliers.contacts')" name="contacts"><action-head :title="t('suppliers.contacts')" :button="t('suppliers.addContact')" @add="openContact"/><el-table :data="contacts"><el-table-column :label="t('suppliers.name')" prop="name"/><el-table-column :label="t('suppliers.department')" prop="department"/><el-table-column :label="t('suppliers.phone')" prop="phone"/><el-table-column :label="t('suppliers.email')" prop="email"/><el-table-column :label="t('suppliers.primary')"><template #default="{row}"><el-tag v-if="row.isPrimary" type="success">{{t('suppliers.primary')}}</el-tag></template></el-table-column><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="remove('contacts',row.id)">{{t('common.deactivate')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.capabilities')" name="capabilities"><action-head :title="t('suppliers.capabilities')" :button="t('suppliers.addCapability')" @add="capabilityOpen=true"/><el-table :data="capabilities"><el-table-column :label="t('suppliers.productCategory')" prop="productCategory"/><el-table-column :label="t('suppliers.process')" prop="process"/><el-table-column :label="t('suppliers.monthlyCapacity')"><template #default="{row}">{{row.monthlyCapacity}} {{row.capacityUnit}}</template></el-table-column><el-table-column label="MOQ" prop="moq"/><el-table-column :label="t('suppliers.leadTime')" prop="leadTimeDays"/><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="remove('capabilities',row.id)">{{t('common.delete')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.certificates')" name="certificates"><action-head :title="t('suppliers.certificates')" :button="t('suppliers.addCertificate')" @add="certificateOpen=true"/><el-table :data="certificates"><el-table-column :label="t('suppliers.certificateName')" prop="name"/><el-table-column :label="t('suppliers.certificateNo')" prop="certificateNo"/><el-table-column :label="t('suppliers.validPeriod')"><template #default="{row}">{{row.issuedOn||'—'}} ~ {{row.expiresOn||'—'}}</template></el-table-column><el-table-column :label="t('common.status')"><template #default="{row}">{{certificateStatus(row.status)}}</template></el-table-column><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="remove('certificates',row.id)">{{t('common.delete')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.owners')" name="owners"><action-head :title="t('suppliers.owners')" :button="t('suppliers.addOwner')" @add="ownerOpen=true"/><el-table :data="owners"><el-table-column :label="t('suppliers.name')" prop="employeeName"/><el-table-column :label="t('suppliers.responsibility')" prop="responsibilityCode"/><el-table-column :label="t('suppliers.primary')"><template #default="{row}"><el-tag v-if="row.isPrimary" type="success">{{t('suppliers.primary')}}</el-tag></template></el-table-column><el-table-column :label="t('common.actions')"><template #default="{row}"><el-button link type="danger" @click="remove('owners',row.id)">{{t('common.deactivate')}}</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane :label="t('suppliers.changes')" name="changes"><el-timeline><el-timeline-item v-for="c in changes" :key="c.id" :timestamp="new Date(c.createdAt).toLocaleString()"><strong>{{changeSummary(c)}}</strong><p>{{operatorName(c.operatorName)||'—'}} · {{changeSection(c.section)}}</p></el-timeline-item></el-timeline></el-tab-pane></el-tabs></el-card>

<el-dialog v-model="editOpen" :title="t('suppliers.editProfile')" width="680px"><el-form :model="edit" label-width="140px" class="grid"><el-form-item :label="t('suppliers.belongsSupplier')" class="full"><el-select v-model="edit.supplierId"><el-option v-for="s in suppliers" :key="s.id" :label="`${s.code} · ${locale==='zh'?s.nameZh||s.nameEn||s.name:s.nameEn||s.nameZh||s.name}`" :value="s.id"/></el-select></el-form-item><el-form-item :label="t('suppliers.factoryName')"><el-input v-model="edit.nameZh"/></el-form-item><el-form-item :label="t('suppliers.factoryNameEn')"><el-input v-model="edit.nameEn"/></el-form-item><el-form-item :label="t('suppliers.country')"><el-select v-model="edit.countryCode" filterable><el-option v-for="c in countryOptions(locale)" :key="c.code" :label="c.name" :value="c.code"/></el-select></el-form-item><el-form-item :label="t('suppliers.timezone')"><el-input v-model="edit.timezone"/></el-form-item><el-form-item :label="t('suppliers.city')"><el-input v-model="edit.city"/></el-form-item><el-form-item :label="t('common.status')"><el-select v-model="edit.status"><el-option v-for="s in statuses" :key="s" :label="statusLabel(s)" :value="s"/></el-select></el-form-item><el-form-item v-if="String(edit.supplierId)!==String(factory.supplierId)" :label="t('suppliers.transferReason')" class="full" required><el-input v-model="edit.transferReason"/></el-form-item><el-form-item :label="t('suppliers.factoryAddress')" class="full"><el-input v-model="edit.address"/></el-form-item><el-form-item :label="t('suppliers.remark')" class="full"><el-input v-model="edit.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="editOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveProfile">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="contactOpen" :title="t('suppliers.addContact')" width="500px"><el-form :model="contact" label-width="100px"><el-form-item :label="t('suppliers.name')"><el-input v-model="contact.name"/></el-form-item><el-form-item :label="t('suppliers.department')"><el-input v-model="contact.department"/></el-form-item><el-form-item :label="t('suppliers.phone')"><el-input v-model="contact.phone"/></el-form-item><el-form-item :label="t('suppliers.email')"><el-input v-model="contact.email"/></el-form-item><el-form-item><el-checkbox v-model="contact.isPrimary">{{t('suppliers.primary')}}</el-checkbox></el-form-item></el-form><template #footer><el-button @click="contactOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveContact">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="ownerOpen" :title="t('suppliers.addOwner')" width="500px"><el-form :model="owner" label-width="110px"><el-form-item :label="t('suppliers.employee')"><el-select v-model="owner.employeeId" filterable @change="employeeChanged"><el-option v-for="e in employees" :key="e.id" :label="`${e.employeeNo} · ${e.name}`" :value="e.id"/></el-select></el-form-item><el-form-item :label="t('suppliers.responsibility')"><el-select v-model="owner.responsibilityCode"><el-option v-for="o in ownerOptions" :key="o.code" :label="o.label" :value="o.code"/></el-select></el-form-item><el-form-item><el-checkbox v-model="owner.isPrimary">{{t('suppliers.primary')}}</el-checkbox></el-form-item></el-form><template #footer><el-button @click="ownerOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveOwner">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="capabilityOpen" :title="t('suppliers.addCapability')" width="520px"><el-form :model="capability" label-width="130px"><el-form-item :label="t('suppliers.productCategory')"><el-input v-model="capability.productCategory"/></el-form-item><el-form-item :label="t('suppliers.process')"><el-input v-model="capability.process"/></el-form-item><el-form-item :label="t('suppliers.monthlyCapacity')"><el-input v-model="capability.monthlyCapacity"><template #append><el-input v-model="capability.capacityUnit"/></template></el-input></el-form-item><el-form-item label="MOQ"><el-input v-model="capability.moq"/></el-form-item><el-form-item :label="t('suppliers.leadTime')"><el-input-number v-model="capability.leadTimeDays" :min="0"/></el-form-item></el-form><template #footer><el-button @click="capabilityOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveCapability">{{t('common.save')}}</el-button></template></el-dialog>
<el-dialog v-model="certificateOpen" :title="t('suppliers.addCertificate')" width="520px"><el-form :model="certificate" label-width="120px"><el-form-item :label="t('suppliers.certificateName')"><el-input v-model="certificate.name"/></el-form-item><el-form-item :label="t('suppliers.certificateNo')"><el-input v-model="certificate.certificateNo"/></el-form-item><el-form-item :label="t('suppliers.validPeriod')"><el-date-picker v-model="certificate.dates" type="daterange" value-format="YYYY-MM-DD"/></el-form-item><el-form-item :label="t('common.status')"><el-select v-model="certificate.status"><el-option v-for="s in certificateStatuses" :key="s" :label="certificateStatus(s)" :value="s"/></el-select></el-form-item></el-form><template #footer><el-button @click="certificateOpen=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="saveCertificate">{{t('common.save')}}</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import {computed,defineComponent,h,onMounted,reactive,ref} from 'vue';import {ElButton,ElMessage,ElMessageBox} from 'element-plus';import {useI18n} from 'vue-i18n';import {useRoute,useRouter} from 'vue-router';import {del,get,post,put} from '../api';import {countryName,countryOptions} from '../lib/countries';import {certificateStatusLabel,changeSectionLabel,changeSummaryLabel,operatorDisplayName} from '../lib/masterDataDisplay';import {useAuthStore} from '../stores/auth';const ActionHead=defineComponent({props:{title:String,button:String},emits:['add'],setup(p,{emit}){return()=>h('div',{class:'action-head'},[h('h3',p.title),h(ElButton,{type:'primary',onClick:()=>emit('add')},()=>p.button)])}})
const {t,locale}=useI18n(),route=useRoute(),router=useRouter(),auth=useAuthStore(),id=String(route.params.id);const factory=ref<any>(),suppliers=ref<any[]>([]),employees=ref<any[]>([]),ownerOptions=ref<any[]>([]),loading=ref(false),tab=ref('profile'),editOpen=ref(false),contactOpen=ref(false),ownerOpen=ref(false),capabilityOpen=ref(false),certificateOpen=ref(false),contacts=ref<any[]>([]),owners=ref<any[]>([]),capabilities=ref<any[]>([]),certificates=ref<any[]>([]),changes=ref<any[]>([]);const edit=reactive<any>({}),contact=reactive({name:'',department:'',title:'',phone:'',email:'',isPrimary:false,remark:''}),owner=reactive<any>({employeeId:'',employeeName:'',responsibilityCode:'PROCUREMENT',isPrimary:false}),capability=reactive({productCategory:'',process:'',monthlyCapacity:'',capacityUnit:'PCS',moq:'',leadTimeDays:0,periodLabel:'',confirmedOn:'',remark:''}),certificate=reactive<any>({name:'',certificateNo:'',dates:[],status:'VALID',fileKey:'',remark:''});const statuses=['PREPARING','COOPERATING','SUSPENDED','INACTIVE'];const certificateStatuses=['VALID','EXPIRING','EXPIRED','SUSPENDED'];const displayName=computed(()=>locale.value==='zh'?factory.value?.nameZh||factory.value?.nameEn:factory.value?.nameEn||factory.value?.nameZh);const currentSupplier=computed(()=>suppliers.value.find(s=>String(s.id)===String(factory.value?.supplierId)));const supplierName=computed(()=>locale.value==='zh'?currentSupplier.value?.nameZh||currentSupplier.value?.nameEn||currentSupplier.value?.name:currentSupplier.value?.nameEn||currentSupplier.value?.nameZh||currentSupplier.value?.name||'');function statusLabel(s:string){return t(`suppliers.factoryStatus.${s}`)}function certificateStatus(s:string){return certificateStatusLabel(s,t)}function changeSummary(c:any){return changeSummaryLabel(c,'factory',t)}function changeSection(v:string){return changeSectionLabel(v,t)}function operatorName(v:string){return operatorDisplayName(v,t)}
async function load(){loading.value=true;try{const d=await get<any>(`/factories/${id}`);factory.value=d.factory;Object.assign(edit,d.factory,{transferReason:''})}finally{loading.value=false}}async function loadTab(){const map:any={contacts:'contacts',owners:'owners',capabilities:'capabilities',certificates:'certificates',changes:'changes'};if(!map[tab.value])return;const d=await get<any>(`/factories/${id}/${map[tab.value]}`);({contacts,owners,capabilities,certificates,changes} as any)[tab.value].value=d[map[tab.value]]||[]}
async function saveProfile(){await put(`/factories/${id}`,{id,factory:edit,transferReason:edit.transferReason});editOpen.value=false;ElMessage.success(t('suppliers.saved'));load()}function openContact(){Object.assign(contact,{name:'',department:'',title:'',phone:'',email:'',isPrimary:false,remark:''});contactOpen.value=true}async function saveContact(){await post(`/factories/${id}/contacts`,{contact});contactOpen.value=false;loadTab()}function employeeChanged(v:string){owner.employeeName=employees.value.find(e=>String(e.id)===String(v))?.name||''}async function saveOwner(){await post(`/factories/${id}/owners`,{owner});ownerOpen.value=false;loadTab()}async function saveCapability(){await post(`/factories/${id}/capabilities`,{capability});capabilityOpen.value=false;loadTab()}async function saveCertificate(){await post(`/factories/${id}/certificates`,{certificate:{...certificate,issuedOn:certificate.dates?.[0]||'',expiresOn:certificate.dates?.[1]||''}});certificateOpen.value=false;loadTab()}async function remove(kind:string,rowId:string){await ElMessageBox.confirm(t('suppliers.confirmDeactivate'));await del(`/factories/${id}/${kind}/${rowId}`);loadTab()}
onMounted(async()=>{await load();const [s,e,o]=await Promise.all([get<any>('/suppliers',{page:1,page_size:200,status:'ALL'}),get<any>('/employees',{page:1,page_size:200,status:'ACTIVE'}),get<any>('/options',{category:'FACTORY_OWNER_RESPONSIBILITY'})]);suppliers.value=s.suppliers||[];employees.value=e.employees||[];ownerOptions.value=o.options||[]})
</script>
<style scoped>.hero{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(120deg,#f2f8fa,#fff);border:1px solid #dce6eb;border-radius:16px;padding:22px 26px;margin:12px 0 18px}.hero h2{margin:4px 0;color:#18324a}.hero p{color:#718392}.action-head{display:flex;justify-content:space-between;align-items:center}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.grid .full{grid-column:1/-1}.grid :deep(.el-select){width:100%}.el-timeline p{color:#82909b}@media(max-width:800px){.grid{grid-template-columns:1fr}.grid .full{grid-column:auto}}</style>
